<?php
// SPDX-License-Identifier: Apache-2.0
declare(strict_types=1);

namespace Sangam\Sdk\Tests;

use PHPUnit\Framework\TestCase;
use Sangam\Sdk\Http\RetryPolicy;
use Sangam\Sdk\Log\CallbackLogger;
use Sangam\Sdk\Model\ExternalWork;
use Sangam\Sdk\Model\LockState;
use Sangam\Sdk\Model\TopicRequest;
use Sangam\Sdk\Model\WorkOperation;
use Sangam\Sdk\SangamClient;
use Sangam\Sdk\Tests\Support\FakeSender;

/**
 * Drift guard: the PHP SDK against the contract sangam-rest/api/sangam-api.yaml (generated by gen_openapi.py).
 * Typed models must have exactly the schema's properties; request bodies sent with every optional argument must
 * carry exactly the schema's properties, and sent with only the required arguments exactly its required ones (no
 * null or absent optional is ever sent). A contract change without the matching SDK change fails here.
 */
final class ContractGuardTest extends TestCase
{
    private const YAML = __DIR__ . '/../../../sangam-rest/api/sangam-api.yaml';

    /** @var array<string, array{properties: list<string>, required: list<string>}> */
    private static array $cache = [];

    private FakeSender $sender;
    private SangamClient $client;

    protected function setUp(): void
    {
        $this->sender = new FakeSender();
        $this->client = new SangamClient('http://sangam.test', logger: new CallbackLogger(static function (): void {
        }), retryPolicy: RetryPolicy::none(), sender: $this->sender);
    }

    /**
     * Properties and required members of components.schemas.<name>, read from the generator's PyYAML block
     * layout: schema keys at indent 4, its sections at 6, property names at 8, required items as "      - name".
     *
     * @return array{properties: list<string>, required: list<string>}
     */
    private static function schema(string $name): array
    {
        if (isset(self::$cache[$name])) {
            return self::$cache[$name];
        }
        self::assertFileExists(self::YAML);
        $lines = preg_split('/\R/', (string) file_get_contents(self::YAML)) ?: [];
        $at = array_search('  schemas:', $lines, true);
        self::assertIsInt($at, 'components.schemas not found');
        $start = null;
        for ($i = $at + 1, $n = count($lines); $i < $n; $i++) {
            if ($lines[$i] === '    ' . $name . ':') {
                $start = $i;
                break;
            }
        }
        self::assertNotNull($start, 'schema ' . $name . ' not found in the contract');
        $props = [];
        $required = [];
        $section = null;
        for ($i = $start + 1, $n = count($lines); $i < $n; $i++) {
            $l = $lines[$i];
            if (trim($l) === '') {
                continue;
            }
            if (strlen($l) - strlen(ltrim($l, ' ')) < 6) {
                break;
            }
            if (preg_match('/^      ([A-Za-z_$][A-Za-z0-9_$]*):/', $l, $m) === 1) {
                $section = $m[1];
            } elseif ($section === 'properties' && preg_match('/^        ([A-Za-z0-9_$]+):/', $l, $m) === 1) {
                $props[] = $m[1];
            } elseif ($section === 'required' && preg_match('/^      - (\S+)$/', $l, $m) === 1) {
                $required[] = $m[1];
            }
        }
        self::assertNotEmpty($props, 'schema ' . $name . ' has no properties (contract layout changed?)');
        return self::$cache[$name] = ['properties' => $props, 'required' => $required];
    }

    /** @param list<string> $a */
    private static function sorted(array $a): array
    {
        sort($a);
        return $a;
    }

    /** @return list<string> constructor parameter names (promoted properties = wire names) */
    private static function params(string $class, bool $requiredOnly = false): array
    {
        $out = [];
        foreach ((new \ReflectionClass($class))->getConstructor()?->getParameters() ?? [] as $p) {
            if (!$requiredOnly || !$p->isOptional()) {
                $out[] = $p->getName();
            }
        }
        return $out;
    }

    // ---------------------------------------------------------------- typed models

    public function testResponseModelsHaveExactlyTheContractProperties(): void
    {
        foreach ([ExternalWork::class => 'ExternalWork', WorkOperation::class => 'WorkOperation',
                     LockState::class => 'LockState'] as $class => $schema) {
            self::assertSame(self::sorted(self::schema($schema)['properties']), self::sorted(self::params($class)), $schema);
        }
    }

    /** @return list<string> constructor parameters whose type does not allow null (= the members the model requires) */
    private static function nonNullable(string $class): array
    {
        $out = [];
        foreach ((new \ReflectionClass($class))->getConstructor()?->getParameters() ?? [] as $p) {
            $t = $p->getType();
            if ($t !== null && !$t->allowsNull()) {
                $out[] = $p->getName();
            }
        }
        return $out;
    }

    public function testModelRequiredMembersMatchTheContract(): void
    {
        // same rule as the Java, Python, TypeScript and .NET guards: a member is non-nullable exactly when the
        // contract requires it, so an optional member is never invented or defaulted
        foreach ([ExternalWork::class => 'ExternalWork', WorkOperation::class => 'WorkOperation',
                     LockState::class => 'LockState', TopicRequest::class => 'TopicRequest'] as $class => $schema) {
            self::assertSame(self::sorted(self::schema($schema)['required']), self::sorted(self::nonNullable($class)), $schema);
        }
    }

    public function testAbsentResponseMembersStayNull(): void
    {
        foreach ([ExternalWork::fromArray([]), WorkOperation::fromArray([]), LockState::fromArray([])] as $model) {
            foreach (get_object_vars($model) as $name => $value) {
                self::assertNull($value, get_class($model) . '::$' . $name . ' was defaulted');
            }
        }
    }

    public function testTopicRequestMatchesTheContract(): void
    {
        $s = self::schema('TopicRequest');
        self::assertSame(self::sorted($s['properties']), self::sorted(self::params(TopicRequest::class)));
        self::assertSame(self::sorted($s['required']), self::sorted(self::params(TopicRequest::class, true)));
        $full = new TopicRequest('t', 1000, ['a'], true, 'p', 'b');
        self::assertSame(self::sorted($s['properties']), self::sorted(array_keys($full->toArray())));
        self::assertSame(self::sorted($s['required']), self::sorted(array_keys((new TopicRequest('t'))->toArray())));
    }

    // ---------------------------------------------------------------- request bodies

    /** @return list<string> top-level keys of the last request body sent */
    private function lastKeys(): array
    {
        $calls = $this->sender->calls;
        $body = $calls[count($calls) - 1]['body'];
        return self::sorted(array_keys(is_array($body) ? $body : []));
    }

    private function assertBodies(string $schema, \Closure $full, \Closure $minimal): void
    {
        $s = self::schema($schema);
        $full();
        self::assertSame(self::sorted($s['properties']), $this->lastKeys(), $schema . ': all optionals set');
        $minimal();
        self::assertSame(self::sorted($s['required']), $this->lastKeys(), $schema . ': required members only');
    }

    public function testWorkerRequestBodies(): void
    {
        $w = $this->client->work();
        $this->assertBodies('FetchAndLockRequest',
            static fn() => $w->fetchAndLock('w', [new TopicRequest('t')], 2, 100, null, true),
            static fn() => $w->fetchAndLock('w', [new TopicRequest('t')], null, null));
        $this->assertBodies('ExtendLockRequest',
            static fn() => $w->extendLock('wk', 'w', 1, 'a', 5000, 'k'),
            static fn() => $w->extendLock('wk', 'w', 1, null, 5000, null));
        $this->assertBodies('WorkCompleteRequest',
            static fn() => $w->complete('wk', 'w', 1, 'a', ['x' => 1], 'k', ['y' => 2], 'ref', ['d' => 1]),
            static fn() => $w->complete('wk', 'w', 1, null, null, null));
        $this->assertBodies('WorkFailRequest',
            static fn() => $w->fail('wk', 'w', 1, 'a', 'm', 'd', 1, 10, 'k'),
            static fn() => $w->fail('wk', 'w', 1, null, null, null, null, null, null));
        $this->assertBodies('WorkBpmnErrorRequest',
            static fn() => $w->bpmnError('wk', 'w', 1, 'a', 'E', 'm', ['x' => 1], 'k'),
            static fn() => $w->bpmnError('wk', 'w', 1, null, 'E', null, null, null));
        $this->assertBodies('WorkUnlockRequest',
            static fn() => $w->unlock('wk', 'w', 1, 'a', 'k'),
            static fn() => $w->unlock('wk', 'w', 1, null, null));
        $this->assertBodies('OutcomeUnknownRequest',
            static fn() => $w->outcomeUnknown('wk', 'w', 1, 'a', 'd', ['e' => 1], 'k'),
            static fn() => $w->outcomeUnknown('wk', 'w', 1, null, null, null, null));
    }

    public function testWorkOutcomeMembersMatchTheContract(): void
    {
        $s = self::schema('WorkOutcome');
        $this->client->work()->complete('wk', 'w', 1, null, null, null, null, 'ref', ['d' => 1]);
        $calls = $this->sender->calls;
        $outcome = $calls[count($calls) - 1]['body']['outcome'];
        self::assertSame(self::sorted($s['properties']), self::sorted(array_keys($outcome)));
        $this->client->work()->complete('wk', 'w', 1, null, null, null, null, 'ref');
        $calls = $this->sender->calls;
        self::assertSame(['reference' => 'ref'], $calls[count($calls) - 1]['body']['outcome']);
    }

    public function testTaskRequestBodies(): void
    {
        $t = $this->client->tasks();
        $this->assertBodies('CompleteTaskRequest',
            static fn() => $t->complete('t', 'h', ['v' => 1], 'APPROVED', 'r', 3, 'f1', 'k', 'RC', 'S1', 'why'),
            static fn() => $t->complete('t', 'h'));
        $this->assertBodies('ReturnTaskRequest',
            static fn() => $t->returnTask('t', 'why', 'RC', 'act', ['v' => 1], 'k', 'S1', 2, 'h', 3),
            static fn() => $t->returnTask('t', 'why'));
    }

    public function testReturnTaskAnswersTheCompleteTaskResult(): void
    {
        $result = ['taskId' => 't', 'processInstanceId' => 'p', 'decision' => 'RETURNED', 'payloadHash' => 'h',
            'instanceEnded' => false, 'nextTaskIds' => ['t2']];
        self::assertSame(self::sorted(self::schema('CompleteTaskResult')['properties']), self::sorted(array_keys($result)));
        $this->sender->reply('return', 200, $result);
        self::assertSame($result, $this->client->tasks()->returnTask('t', 'why'));
    }
}
